-- 0029: 붙임5 4.시공(제작)내용 전용 플레이스홀더 연결(멘토 편집값 반영).
--  업태/종목={{contractor_biztype}}, 휴대전화={{contractor_mobile}}, 시공기간={{construction_period}},
--  외주 업체명 옆 업체지역={{contractor_region}} 병기.

update public.document_templates set html_content=$html$<!doctype html><html lang="ko"><head><meta charset="utf-8"><style> @page{size:A4;margin:14mm 14mm} body{color:#000;font-size:10pt;line-height:1.4} .tag{display:inline-block;border:1px solid #000;background:#f2f2f2;font-weight:700;font-size:11pt;padding:2pt 10pt;margin:0 0 4pt} h1{text-align:center;font-size:18pt;font-weight:800;letter-spacing:0.5px;margin:0 0 10pt} .sec{font-weight:800;font-size:12pt;margin:10pt 0 3pt} table{border-collapse:collapse;width:100%;table-layout:fixed;margin:2pt 0} th,td{border:1px solid #000;padding:3.5pt 5pt;vertical-align:middle} th{background:#f2f2f2;font-weight:700;text-align:center;font-size:10pt} td{text-align:left;font-size:10pt} .sub{font-weight:400;font-size:8.5pt}.rt{text-align:right}.chk{letter-spacing:0.3px} .box{height:34pt;vertical-align:top} .photo{height:118pt;text-align:center;color:#8a8a8a;font-size:9pt;vertical-align:middle} .note{font-size:9pt;color:#333;margin:2pt 1px} .stmtcell{text-align:justify;line-height:1.5;padding:6pt} .sigwho{text-align:left}.sigmark{text-align:center;width:18%} .foot-in{font-weight:800;font-size:11pt} </style></head><body><span class="tag">붙임 5</span><h1>대전 소상공인·자영업자 재기지원사업 경영개선지원 신청서</h1><p class="sec">1. 지원업체 현황</p><table><colgroup><col style="width:19%"><col style="width:31%"><col style="width:19%"><col style="width:31%"></colgroup><tr><th>상 호 명</th><td>{{business_name}}</td><th>사업자등록번호<br><span class="sub">(법인등록번호)</span></th><td>{{business_reg_no}}</td></tr><tr><th>대표자</th><td>{{owner_name}}</td><th>연락처</th><td>{{phone}}</td></tr><tr><th>사업장 주소</th><td colspan="3">{{address}}</td></tr><tr><th>상시근로자<br><span class="sub">(대표자 제외)</span></th><td class="rt">{{employee_count}} 명</td><th>개업연월일</th><td>{{opened_at}}</td></tr><tr><th>업 태</th><td>{{business_type}}</td><th>종 목</th><td>{{item}}</td></tr></table><p class="sec">2. 컨설팅</p><table><colgroup><col style="width:19%"><col style="width:31%"><col style="width:19%"><col style="width:31%"></colgroup><tr><th>성 명<br><span class="sub">(컨설턴트)</span></th><td>{{consultant_name}}</td><th>연락처<br><span class="sub">(컨설턴트)</span></th><td>{{consultant_phone}}</td></tr><tr><th>컨설팅일자</th><td colspan="3">(1차) {{consulting_date_1}} &nbsp;&nbsp; (2차) {{consulting_date_2}} &nbsp;&nbsp; (3차) {{consulting_date_3}}</td></tr></table><p class="sec">3. 경영개선자금 신청내역</p><table><colgroup><col style="width:19%"><col style="width:31%"><col style="width:19%"><col style="width:31%"></colgroup><tr><th>총 신청내역</th><td class="chk" colspan="3">{{cat_hygiene}} 위생관리 &nbsp; {{cat_safety}} 안전관리 &nbsp; {{cat_promo}} 홍보(광고) &nbsp; {{cat_env}} 환경개선 &nbsp; {{cat_pos}} POS경비</td></tr><tr><th>총소요비용</th><td colspan="3">※ 지원금 최대 300만원 (부가가치세는 자부담)</td></tr><tr><th>소요금액<br><span class="sub">(부가세 제외)</span></th><td class="rt">{{cost_excl_vat}} 원</td><th>지원금신청액<br><span class="sub">(소요금액의 100%)</span></th><td class="rt">{{requested_amount}} 원</td></tr><tr><th>시공(제작)내용</th><td colspan="3">{{reason}}</td></tr><tr><th>단위사업</th><td></td><th>소요금액 <span class="sub">(부가세 제외)</span></th><td class="rt">원</td></tr><tr><th>단위사업</th><td></td><th>소요금액 <span class="sub">(부가세 제외)</span></th><td class="rt">원</td></tr><tr><th>단위사업</th><td></td><th>소요금액 <span class="sub">(부가세 제외)</span></th><td class="rt">원</td></tr></table><p class="note">* 필요시 칸 추가 기재</p><p class="sec">4. 시공(제작) 내용 <span class="sub">(외주업체별로 작성 · 필요시 페이지 추가)</span></p><table><colgroup><col style="width:19%"><col style="width:31%"><col style="width:19%"><col style="width:31%"></colgroup><tr><th>단위사업</th><td class="chk" colspan="3">□ 위생관리 &nbsp; □ 안전관리 &nbsp; □ 홍보(광고) &nbsp; □ 환경개선 &nbsp; □ POS경비</td></tr><tr><th>외주 업체명<br><span class="sub">(업체 지역)</span></th><td>{{contractor_name}} {{contractor_region}}</td><th>사업자등록번호</th><td>{{contractor_reg_no}}</td></tr><tr><th>대표자명</th><td>{{contractor_rep}}</td><th>업태/종목</th><td>{{contractor_biztype}}</td></tr><tr><th>사업장 연락처</th><td>{{contractor_phone}}</td><th>휴대전화</th><td>{{contractor_mobile}}</td></tr><tr><th>시공기간</th><td colspan="3">{{construction_period}}</td></tr><tr><th>시공내용</th><td colspan="3">{{contractor_work_type}}</td></tr></table><table style="margin-top:4pt"><colgroup><col style="width:19%"><col style="width:31%"><col style="width:19%"><col style="width:31%"></colgroup><tr><th>단위사업</th><td class="chk" colspan="3">□ 위생관리 &nbsp; □ 안전관리 &nbsp; □ 홍보(광고) &nbsp; □ 환경개선 &nbsp; □ POS경비</td></tr><tr><th>외주 업체명<br><span class="sub">(업체 지역)</span></th><td></td><th>사업자등록번호</th><td></td></tr><tr><th>대표자명</th><td></td><th>업태/종목</th><td></td></tr><tr><th>사업장 연락처</th><td></td><th>휴대전화</th><td></td></tr><tr><th>시공기간</th><td colspan="3">　　월　　일　~　　월　　일</td></tr><tr><th>시공내용</th><td colspan="3"></td></tr></table><table style="margin-top:4pt"><colgroup><col style="width:19%"><col style="width:31%"><col style="width:19%"><col style="width:31%"></colgroup><tr><th>단위사업</th><td class="chk" colspan="3">□ 위생관리 &nbsp; □ 안전관리 &nbsp; □ 홍보(광고) &nbsp; □ 환경개선 &nbsp; □ POS경비</td></tr><tr><th>외주 업체명<br><span class="sub">(업체 지역)</span></th><td></td><th>사업자등록번호</th><td></td></tr><tr><th>대표자명</th><td></td><th>업태/종목</th><td></td></tr><tr><th>사업장 연락처</th><td></td><th>휴대전화</th><td></td></tr><tr><th>시공기간</th><td colspan="3">　　월　　일　~　　월　　일</td></tr><tr><th>시공내용</th><td colspan="3"></td></tr></table><p class="sec">5. 추진계획</p><table><colgroup><col style="width:19%"><col style="width:81%"></colgroup><tr><th>구 분</th><th>주 요 내 용</th></tr><tr><th>사업소개</th><td class="box">{{plan_intro}}</td></tr><tr><th>경영상황</th><td class="box">{{plan_status}}</td></tr><tr><th>지원 필요성</th><td class="box">{{plan_need}}</td></tr><tr><th>기대효과</th><td class="box">{{plan_effect}}</td></tr></table><p class="sec">6. 사업장 사진</p><p class="note">* 현재 사업장 내·외부 사진(간판이 보이게 촬영), 시공할 장소 사진</p><table><colgroup><col style="width:50%"><col style="width:50%"></colgroup><tr><td class="photo">(사업장 사진 첨부)</td><td class="photo">(사업장 사진 첨부)</td></tr><tr><td class="photo">(사업장 사진 첨부)</td><td class="photo">(사업장 사진 첨부)</td></tr><tr><td class="photo">(사업장 사진 첨부)</td><td class="photo">(사업장 사진 첨부)</td></tr></table><table style="margin-top:8pt"><colgroup><col style="width:41%"><col style="width:41%"><col style="width:18%"></colgroup><tr><td class="stmtcell" colspan="3"><b>(수혜대상(대표자))</b> ▶ 본 참여 신청서 및 공고문의 내용을 모두 확인하고 본인이 직접 서명함을 확인합니다. ▶ 서류 누락 또는 공고문 내용을 위반하는 경우 지원 탈락으로 간주함에 동의합니다.</td></tr><tr><td style="text-align:center">{{application_date}}</td><td class="sigwho">신청업체(대표자) {{owner_name}}</td><td class="sigmark">{{{sign_applicant}}}</td></tr><tr><td class="foot-in" style="text-align:center">{{institution}} 귀하</td><td class="sigwho">컨설턴트 {{consultant_name}}</td><td class="sigmark">{{{sign_consultant}}}</td></tr><tr><th rowspan="2">첨부서류</th><td colspan="2" style="text-align:left">【필수】 외주업체 사업자등록증 사본 1부, 견적서 1부(100만원 이상일 경우 견적서 2개 이상), 사업참여 및 중복지원 금지 확약서</td></tr><tr><td colspan="2" style="text-align:left">【해당 시】 옥외광고업 등록증</td></tr></table></body></html>$html$ where template_key='support_application_management';
